#!/bin/bash
#
# Generate dev/external-services/.env with random, local-only credentials.
# The file is gitignored. Existing values are preserved.
#
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="$SCRIPT_DIR/.env"

if [ -f "$ENV_FILE" ]; then
  echo "Using existing $ENV_FILE"
  exit 0
fi

umask 077
cat >"$ENV_FILE" <<EOF
# Generated by gen-env.sh on $(date -Iseconds). Do not commit.
RUSTFS_ACCESS_KEY=dev$(openssl rand -hex 8)
RUSTFS_SECRET_KEY=$(openssl rand -hex 32)
BARMAN_ACCESS_KEY=barman$(openssl rand -hex 6)
BARMAN_SECRET_KEY=$(openssl rand -hex 32)
VAULT_DEV_ROOT_TOKEN=$(openssl rand -hex 24)
EOF

chmod 600 "$ENV_FILE"
echo "Generated $ENV_FILE"
